import{_ as t,o,c as d,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-READ-and-WRITE-Commands.md","filePath":"manual-en/Matrix-READ-and-WRITE-Commands.md","lastUpdated":1785684581000}'),a={name:"manual-en/Matrix-READ-and-WRITE-Commands.md"};function n(c,e,s,m,r,h){return o(),d("div",null,[...e[0]||(e[0]=[i('<h4 id="_16-4-8-the-read-and-write-commands" tabindex="-1">16.4.8 The <code>READ</code> and <code>WRITE</code> Commands <a class="header-anchor" href="#_16-4-8-the-read-and-write-commands" aria-label="Permalink to &quot;16.4.8 The `READ` and `WRITE` Commands&quot;">​</a></h4><p>The <code>READ</code> and <code>WRITE</code> commands perform matrix input and output with text files. They share the following syntax for specifying how data is divided among input lines:</p><pre><code>/FIELD=_first_ TO _last_ [BY _width_]\n[/FORMAT=_format_]\n</code></pre><p>Both commands require the <code>FIELD</code> subcommand. It specifies the range of columns, from first to last, inclusive, that the data occupies on each line of the file. The leftmost column is column 1. The columns must be literal numbers, not expressions. To use entire lines, even if they might be very long, specify a column range such as <code>1 TO 100000</code>.</p><p>The <code>FORMAT</code> subcommand is optional for numerical matrices. For string matrix input and output, specify an <code>A</code> format. In addition to <code>FORMAT</code>, the optional <code>BY</code> specification on <code>FIELD</code> determine the meaning of each text line:</p><ul><li>With neither <code>BY</code> nor <code>FORMAT</code>, the numbers in the text file are in <code>F</code> format separated by spaces or commas. For <code>WRITE</code>, PSPP uses as many digits of precision as needed to accurately represent the numbers in the matrix.</li><li><code>BY _width_</code> divides the input area into fixed-width fields with the given <em>width</em>. The input area must be a multiple of <em>width</em> columns wide. Numbers are read or written as <code>F _width_.0</code> format.</li><li><code>FORMAT=&quot;_count_ F&quot;</code> divides the input area into integer <em>count</em> equal-width fields per line. The input area must be a multiple of <em>count</em> columns wide. Another format type may be substituted for <code>F</code>.</li><li><code>FORMAT=F _w_</code>[<code>._d_</code>] divides the input area into fixed-width fields with width <em>w</em>. The input area must be a multiple of <em>w</em> columns wide. Another format type may be substituted for <code>F</code>. The <code>READ</code> command disregards <em>d</em>.</li><li><code>FORMAT=F</code> specifies format <code>F</code> without indicating a field width. Another format type may be substituted for <code>F</code>. The <code>WRITE</code> command accepts this form, but it has no effect unless <code>BY</code> is also used to specify a field width.</li></ul><p>If <code>BY</code> and <code>FORMAT</code> both specify or imply a field width, then they must indicate the same field width.</p><table tabindex="0"><thead><tr><th>• The READ Command</th><th></th><th></th></tr></thead><tbody><tr><td>• The WRITE Command</td><td></td><td></td></tr></tbody></table>',8)])])}const f=t(a,[["render",n]]);export{u as __pageData,f as default};
